#!/bin/bash
# Vocal Typewriter - Universal Build Script
# Generated by LoomyForge
# Detects OS and runs appropriate build

set -e

echo "🚀 LoomyForge Build System"
echo "Project: Vocal Typewriter"
echo ""

# Detect OS
case "$(uname -s)" in
    Darwin)
        echo "🍎 Detected macOS"
        OS="macos"
        ;;
    MINGW*|CYGWIN*|MSYS*)
        echo "🪟 Detected Windows"
        OS="windows"
        ;;
    Linux)
        echo "🐧 Detected Linux"
        OS="linux"
        ;;
    *)
        echo "❌ Unknown operating system"
        exit 1
        ;;
esac

# Check Node.js
if ! command -v node &> /dev/null; then
    echo "❌ Node.js not found. Install from https://nodejs.org"
    exit 1
fi
echo "✅ Node.js $(node --version)"


# Check Rust (required for Tauri)
if ! command -v cargo &> /dev/null; then
    echo "❌ Rust not found. Install from https://rustup.rs"
    exit 1
fi
echo "✅ Rust $(rustc --version)"

# Check/install bun (commonly used by Tauri projects)
# IMPORTANT: Some bun installers update your shell config but NOT the current script.
# We force PATH for *this* script so it always continues.
BUN_BIN="$HOME/.bun/bin"

if ! command -v bun &> /dev/null; then
    echo "📦 Installing bun (required by this Tauri project)..."
    curl -fsSL https://bun.sh/install | bash
fi

export BUN_INSTALL="$HOME/.bun"
export PATH="$BUN_BIN:$PATH"
hash -r 2>/dev/null || true

if command -v bun &> /dev/null; then
    echo "✅ Bun $(bun --version)"
else
    echo "⚠️ Bun install finished, but bun isn't available in this Terminal yet."
    echo "   Fix: close Terminal, open it again, then run this script again."
    echo "   (Or run: export PATH="$HOME/.bun/bin:$PATH")"
fi


# Install dependencies
echo ""
echo "📦 Installing dependencies..."
npm install

# Build based on OS
echo ""
echo "🔨 Building for $OS..."


npx tauri build


echo ""
echo "✅ Build complete!"
echo "📁 Check the dist/ folder for your installers"
